/* 完整聚焦流程 */
const SID = 'CEILING_A_6F_1';
const obj = ssp.objectsTool.getById(SID);
if (obj) {
  await ssp.cameraController.flyToObject(obj);
  ssp.objectsTool.setHighlight(obj, '#ff5722', true);  // pulse 闪烁更醒目
  console.log(`focused on ${obj.name} at ${obj.userData.sid}`);
} else {
  console.log(`sid not found: ${SID}`);
  // 列出可用 sid: 可用 ssp.scene.traverse 遍历
}
